#!/usr/bin/env python3
"""Simple CLI Todo App"""

import json
import sys
from datetime import datetime

TODO_FILE = "todos.json"


def load_todos():
    """Load todos from file."""
    try:
        with open(TODO_FILE, "r") as f:
            return json.load(f)
    except FileNotFoundError:
        return []


def save_todos(todos):
    """Save todos to file."""
    with open(TODO_FILE, "w") as f:
        json.dump(todos, f, indent=2)


def add_todo(description):
    """Add a new todo."""
    todos = load_todos()
    todo = {
        "description": description,
        "created_at": datetime.now().isoformat(),
        "done": False
    }
    todos.append(todo)
    save_todos(todos)
    print(f"✓ Added: {description}")


def list_todos():
    """List all todos."""
    todos = load_todos()
    if not todos:
        print("No todos yet.")
        return

    for i, todo in enumerate(todos, 1):
        status = "✓" if todo["done"] else "○"
        print(f"{i}. [{status}] {todo['description']}")
        print(f"   Created: {todo['created_at']}")


def done_todo(index):
    """Mark a todo as done."""
    todos = load_todos()
    if not todos:
        print("No todos to mark as done.")
        return

    if index < 1 or index > len(todos):
        print(f"Invalid index. Valid range: 1-{len(todos)}")
        return

    todo = todos[index - 1]
    if todo["done"]:
        print(f"Already done: {todo['description']}")
        return

    todo["done"] = True
    todo["completed_at"] = datetime.now().isoformat()
    save_todos(todos)
    print(f"✓ Completed: {todo['description']}")


def main():
    """Main CLI loop."""
    todos = load_todos()

    print("\n=== Simple Todo App ===")
    print("Commands: add <description>, list, done <index>, quit")
    print("========================\n")

    while True:
        try:
            command = input("> ").strip().lower()

            if command == "quit":
                break
            elif command.startswith("add "):
                description = command[4:]
                add_todo(description)
            elif command == "list":
                list_todos()
            elif command.startswith("done "):
                try:
                    index = int(command[5:])
                    done_todo(index)
                except ValueError:
                    print("Invalid index. Use a number like 'done 1'")
            else:
                print("Unknown command. Try: add, list, done, quit")
        except KeyboardInterrupt:
            print("\n\nGoodbye!")
            break


if __name__ == "__main__":
    main()
